- Gradle
 groovy
repositories {
 exclusiveContent {
 forRepository {
 maven {
 name = "Modrinth"
 url = "https://api.modrinth.com/maven"
 }
 }
 filter {
 includeGroup "maven.modrinth"
 }
 }
}

dependencies {
 modImplementation "maven.modrinth:config-manager:${project.configmanager version}"
}

